import{z as A,x as p,o,c as B,q as l,j as s,D as r,d as e,s as n,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"湖仓与开放表格式","description":"","frontmatter":{"title":"湖仓与开放表格式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lakehouse-table-format.md","filePath":"cs/lakehouse-table-format.md","lastUpdated":1791063341000}'),d={name:"cs/lakehouse-table-format.md"};function c(m,a,u,h,D,f){const E=p("Mermaid");return o(),B("div",null,[a[2]||(a[2]=l('<h1 id="湖仓与开放表格式" tabindex="-1">湖仓与开放表格式 <a class="header-anchor" href="#湖仓与开放表格式" aria-label="Permalink to &quot;湖仓与开放表格式&quot;">​</a></h1><div class="epigraph"><p>对象存储上的 Parquet 不是表：没有事务、没有隔离、没有可靠的 schema 演进。表格式把数据湖补成可被引擎共享的关系。</p><footer>—— 据 Armbrust et al. 对 lakehouse；Delta Lake / Apache Iceberg / Apache Hudi 的公开设计</footer></div><p><a href="/cs/olap-cube">上一课</a>假定有一张可维护的事实表。缺口是文件堆：数仓一体机贵，HDFS 上的目录又没有 ACID。本课钉湖仓与开放表格式；MapReduce 下一课才讲批计算模型。不把对象存储当新的 B+ 树重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>湖：廉价存储 + schema-on-read，丢了主键、并发写、时间旅行。仓：强事务，锁进专有格式。表格式（Iceberg/Delta/Hudi）在对象存储上加：快照隔离、分区演进、列投影、可重放的提交日志。缺口是<strong>元数据如何成为真值</strong>，不是再夸一次列存。</p><p><span class="marginnote">多引擎（Spark、Trino、Flink）共用同一快照，才叫开放。只给一个引擎写的「湖」仍是专有仓。</span></p><p><span class="marginnote">直觉类比：每次提交像一次 git commit——数据文件是只增不删的工作区，元数据日志是提交历史，所谓「时间旅行」不过是 checkout 回某个旧提交再看表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一次提交：manifest / transaction log 指向不可变文件。写：copy-on-write 或 merge-on-read。compaction 把小文件合并。与立方：物化视图可以挂在表快照上。与流：changelog 表是后课 exactly-once 的落点。</p>',9)),(o(),s(i,null,{default:r(()=>[n(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%E6%96%87%E4%BB%B6%22%5D%20--%3E%20META%5B%22%E5%BF%AB%E7%85%A7%20%2F%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20META%20--%3E%20ENG%5B%22%E5%A4%9A%E5%BC%95%E6%93%8E%E5%8F%AA%E8%AF%BB%E5%90%8C%E4%B8%80%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("不可变文件 + 原子换根指针 ≈ "),t("a",{href:"/cs/shadow-paging"},"影子分页"),e(" 在对象存储上的亲戚，也像 LSM 切根。隔离来自「读一个快照 ID」，不是行锁；跨表 2PC 通常没有或很弱，不要当 Spanner。小文件问题来自列出与打开成本，compaction 合并——表级 LSM。delete file / merge-on-read 让读时合并删除位，读放大上升。")],-1)),a[5]||(a[5]=t("p",null,[e("并发写：条件 put 或锁服务提交元数据，冲突则 abort 重试。时间旅行等于选旧快照。schema 演进写进元数据，读侧按字段投影，与 "),t("a",{href:"/cs/schema-migration"},"模式迁移"),e(" 的文件版对齐。TDE 在对象存储侧，密钥合同单独写。")],-1)),(o(),s(i,null,{default:r(()=>[n(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E5%85%A5%E6%96%B0%E7%9A%84%E4%B8%8D%E5%8F%AF%E5%8F%98%E6%95%B0%E6%8D%AE%E6%96%87%E4%BB%B6%22%5D%20--%3E%20META%5B%22%E5%86%99%E6%96%B0%E5%85%83%E6%95%B0%E6%8D%AE%3A%20%E6%96%B0%E5%BF%AB%E7%85%A7%E6%8C%87%E5%90%91%E6%96%B0%E6%97%A7%E6%96%87%E4%BB%B6%E9%9B%86%22%5D%0A%20%20META%20--%3E%20CAS%5B%22%E5%8E%9F%E5%AD%90%E6%8D%A2%E6%A0%B9%E6%8C%87%E9%92%88%3A%20%E6%9D%A1%E4%BB%B6%20put%20%E6%88%96%E9%94%81%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20CAS%20--%3E%7C%22%E6%88%90%E5%8A%9F%22%7C%20NEW%5B%22%E5%90%8E%E7%BB%AD%E8%AF%BB%E8%80%85%E6%8B%BF%E6%96%B0%E5%BF%AB%E7%85%A7%20ID%22%5D%0A%20%20CAS%20--%3E%7C%22%E8%A2%AB%E6%8A%A2%E5%85%88%22%7C%20ABORT%5B%22%E6%8F%90%E4%BA%A4%E4%BD%9C%E5%BA%9F%2C%20%E6%95%B4%E4%BD%93%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字实例：一个每 5 分钟 flush 一次的管道，一天能写出 288 个小 Parquet，对象存储光「列目录+开文件头」就能拖垮查询规划。compaction 把它们并成几个几百 MB 的文件，规划期元数据开销直降一个数量级——这就是「表级 LSM」的日常账。</span></p><p><span class="marginnote">常见误区：初学者容易以为湖仓能顶替 OLTP 数据库。表格式给的是快照隔离与秒级提交，没有行锁、没有毫秒级事务；高并发单行更新的场景（扣库存、改余额）仍然要回 OLTP，湖仓只管分析侧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较 Iceberg / Delta / Hudi 的每一条 SQL。下一课 MapReduce 是计算模型，不是表。不要把湖仓写成已经取代 OLTP：提交延迟与行锁粒度都不在同一档。流写入必须控制批次，否则小文件打爆元数据。</p><p>后课默认：分析表用开放格式快照；跨引擎共享的是文件集，不是缓冲池。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>表格式把对象存储补上快照与演进，才成为多引擎的表。</li><li>元数据日志是真值；数据文件只追加；compaction 管小文件。</li><li>MapReduce 下一课。</li><li>出处：Armbrust 等 lakehouse；Iceberg / Delta / Hudi 设计文档。</li></ul>',7))])}const g=A(d,[["render",c]]);export{T as __pageData,g as default};
